-- Private editorial research queue. All topics are explicitly NOT VERIFIED.
-- No visitor queries are stored. Entries are from a curated 60-question benchmark.
-- Only a qualified Admin can advance source checks or link a published article.
CREATE TABLE IF NOT EXISTS research_topics(
 id TEXT PRIMARY KEY,
 domain TEXT NOT NULL CHECK(domain IN ('quranic_themes','sunnah','seerah','prophetic_medicine','living_guidance')),
 question TEXT NOT NULL,
 research_stage TEXT NOT NULL DEFAULT 'queued' CHECK(research_stage IN ('queued','researching','source_check','scholar_review','medical_review','ready_for_article','closed')),
 risk_class TEXT NOT NULL DEFAULT 'general' CHECK(risk_class IN ('general','interpretation','hadith_grade','historical','medical','jurisprudence')),
 source_notes TEXT NOT NULL DEFAULT '',
 assigned_reviewer TEXT NOT NULL DEFAULT '',
 linked_article_id TEXT REFERENCES encyclopedia_articles(id),
 sort_order INTEGER NOT NULL DEFAULT 0,
 updated_at TEXT NOT NULL DEFAULT(datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_research_topics_stage ON research_topics(research_stage,domain,sort_order);
CREATE UNIQUE INDEX IF NOT EXISTS idx_research_topics_question ON research_topics(domain,question);
